{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.KA_ASP_INVENTORY_FACT_ITEMS AS WITH sku_mapping AS ( SELECT DISTINCT TRIM(UPPER(COMMONSKU)) AS commonsku, Name AS standard_product_name FROM `kerala-ayurveda-wh.MapleMonk.FINAL_SKU_MASTER` WHERE MARKETPLACE IN (\'AMAZON SELLER CENTRAL INDIA SESSIONS API\', \'AMAZON SELLER CENTRAL INDIA\') ), joined_data AS ( SELECT a.* EXCEPT(product_name), b.COMMONSKU AS raw_COMMONSKU, b.Name AS raw_product_name, CASE WHEN b.COMMONSKU LIKE \'%-2\' THEN 2 WHEN b.COMMONSKU LIKE \'%-3\' THEN 3 WHEN b.COMMONSKU LIKE \'%-4\' THEN 4 WHEN b.COMMONSKU LIKE \'%-6\' THEN 6 ELSE 1 END AS multiplier, TRIM(SPLIT(b.COMMONSKU, \'-\')[OFFSET(0)]) AS base_sku FROM `kerala-ayurveda-wh.MapleMonk.Ka_india_new_GET_FBA_INVENTORY_PLANNING_DATA` a LEFT JOIN `kerala-ayurveda-wh.MapleMonk.FINAL_SKU_MASTER` b ON TRIM(UPPER(a.sku)) = TRIM(UPPER(b.Marketplace_SKU)) AND b.MARKETPLACE IN (\'AMAZON SELLER CENTRAL INDIA SESSIONS API\', \'AMAZON SELLER CENTRAL INDIA\') ) SELECT jd.sku, jd.asin, jd.fnsku, jd.base_sku AS COMMONSKU, COALESCE(sm.standard_product_name, jd.raw_product_name) AS product_name, jd.marketplace, DATE(jd.snapshot_date) AS snapshot_date, SAFE_CAST(CAST(NULLIF(TRIM(jd.available), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS available, SAFE_CAST(CAST(NULLIF(TRIM(jd.reserved_quantity), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS reserved_quantity, SAFE_CAST(CAST(NULLIF(TRIM(jd.unfulfillable_quantity), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS unfulfillable_quantity, SAFE_CAST(CAST(NULLIF(TRIM(jd.inbound_shipped), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS inbound_shipped, SAFE_CAST(CAST(NULLIF(TRIM(jd.inbound_working), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS inbound_working, SAFE_CAST(CAST(NULLIF(TRIM(jd.inbound_quantity), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS inbound_quantity, SAFE_CAST(CAST(NULLIF(TRIM(jd.inbound_received), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS inbound_received, SAFE_CAST(NULLIF(TRIM(jd.sell_through), \'\') AS FLOAT64) * jd.multiplier AS sell_through, SAFE_CAST(CAST(NULLIF(TRIM(jd.units_shipped_t7), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS units_shipped_t7, SAFE_CAST(CAST(NULLIF(TRIM(jd.units_shipped_t30), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS units_shipped_t30, SAFE_CAST(CAST(NULLIF(TRIM(jd.units_shipped_t60), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS units_shipped_t60, SAFE_CAST(CAST(NULLIF(TRIM(jd.units_shipped_t90), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS units_shipped_t90, SAFE_CAST(CAST(NULLIF(TRIM(jd.sales_shipped_last_7_days), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS sales_shipped_last_7_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.sales_shipped_last_30_days), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS sales_shipped_last_30_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.sales_shipped_last_60_days), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS sales_shipped_last_60_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.sales_shipped_last_90_days), \'\') AS FLOAT64) AS INT64) * jd.multiplier AS sales_shipped_last_90_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_0_to_30_days), \'\') AS FLOAT64) AS INT64) AS inv_age_0_to_30_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_31_to_60_days), \'\') AS FLOAT64) AS INT64) AS inv_age_31_to_60_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_61_to_90_days), \'\') AS FLOAT64) AS INT64) AS inv_age_61_to_90_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_91_to_180_days), \'\') AS FLOAT64) AS INT64) AS inv_age_91_to_180_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_181_to_270_days), \'\') AS FLOAT64) AS INT64) AS inv_age_181_to_270_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_271_to_365_days), \'\') AS FLOAT64) AS INT64) AS inv_age_271_to_365_days, SAFE_CAST(CAST(NULLIF(TRIM(jd.inv_age_365_plus_days), \'\') AS FLOAT64) AS INT64) AS inv_age_365_plus_days, SAFE_CAST(NULLIF(TRIM(jd.days_of_supply), \'\') AS FLOAT64) AS days_of_supply, SAFE_CAST(NULLIF(TRIM(jd.weeks_of_cover_t30), \'\') AS FLOAT64) AS weeks_of_cover_t30, SAFE_CAST(NULLIF(TRIM(jd.weeks_of_cover_t90), \'\') AS FLOAT64) AS weeks_of_cover_t90, SAFE_CAST(NULLIF(TRIM(jd.storage_volume), \'\') AS FLOAT64) AS storage_volume, SAFE_CAST(NULLIF(TRIM(jd.item_volume), \'\') AS FLOAT64) AS item_volume, jd.volume_unit_measurement, SAFE_CAST(NULLIF(TRIM(jd.your_price), \'\') AS FLOAT64) AS your_price, SAFE_CAST(NULLIF(TRIM(jd.sales_price), \'\') AS FLOAT64) AS sales_price, SAFE_CAST(NULLIF(TRIM(jd.lowest_price_used), \'\') AS FLOAT64) AS lowest_price_used, SAFE_CAST(NULLIF(TRIM(jd.lowest_price_new_plus_shipping), \'\') AS FLOAT64) AS lowest_price_new_plus_shipping FROM joined_data jd LEFT JOIN sku_mapping sm ON TRIM(UPPER(jd.base_sku)) = sm.commonsku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            